// Space: O(1)

class Solution {
public:
    bool isOneBitCharacter(vector<int>& bits) {
        auto parity = 0;
        for (int i = static_cast<int>(bits.size()) - 2;
             i >= 0 && bits[i]; --i) {
            parity ^= bits[i];
        }
        return parity == 0;
    }
};

