class Cashier {
public:
    Cashier(int n, int discount, vector<int>& products, vector<int>& prices)
      : n_{n}
      , discount_{discount}
      , curr_{0}
    {
        for (int i = 0; i < products.size(); ++i) {
            lookup_[products[i]] = prices[i];
        }
