        for (int i = 0, j = -1; i < size(s1); ++i) {
            if (s1[i] == s2[i]) {
                continue;
            }
            tie(curr, prev) = pair(min(curr + x, j != -1 ? prev + (i - j) * 2 : INF), curr);
