kamyu-c-array-transformation-1k7vrxb:
// Time:  O(n^2)
// Space: O(n)

class Solution {
public:
    vector<int> transformArray(vector<int>& arr) {    
        while (is_changable(arr)) {
            auto new_arr = arr;
            for (int i = 1; i + 1 < arr.size(); ++i) {
                new_arr[i] += int(arr[i - 1] > arr[i] && arr[i] < arr[i + 1]);
                new_arr[i] -= int(arr[i - 1] < arr[i] && arr[i] > arr[i + 1]);
            }
            arr = move(new_arr);
        }
        return arr;
    }

private:
    bool is_changable(const vector<int>& arr) {
        for (int i = 1; i + 1 < arr.size(); ++i) {
            if ((arr[i - 1] > arr[i] && arr[i] < arr[i + 1]) ||
                (arr[i - 1] < arr[i] && arr[i] > arr[i + 1])) {
                return true;
            }
        }
        return false;
    }
};

kamyu-c-array-with-elements-not-equal-to:
// Time:  O(n) ~ O(n^2), O(n) on average
// Space: O(1)

// Tri Partition (aka Dutch National Flag Problem) with virtual index solution
class Solution {
public:
    vector<int> rearrangeArray(vector<int>& nums) {
        int mid = (size(nums) - 1) / 2;
        nth_element(begin(nums), begin(nums) + mid, end(nums));  // O(n) ~ O(n^2) time
        reversedTriPartitionWithVI(nums, nums[mid]);  // O(n) time, O(1) space
        return nums;
    }

private:
    void reversedTriPartitionWithVI(vector<int>& nums, int val) {
        const int N = size(nums) / 2 * 2 + 1;
        #define Nums(i) nums[(1 + 2 * (i)) % N]
        for (int i = 0, j = 0, n = size(nums) - 1; j <= n;) {
            if (Nums(j) > val) {
                swap(Nums(i++), Nums(j++));
            } else if (Nums(j) < val) {
                swap(Nums(j), Nums(n--));
            } else {
                ++j;
            }
        }
    }
};

// Time:  O(nlogn)
// Space: O(n)
// Sorting and reorder solution
class Solution2 {
public:
    vector<int> rearrangeArray(vector<int>& nums) {
        int mid = (size(nums) - 1) / 2;
        sort(begin(nums), end(nums));  // O(nlogn) time
        vector<int> result(size(nums));  // O(n) space
        for (int i = 0, smallEnd = mid;  i < size(nums); i += 2, --smallEnd) {
            result[i] = nums[smallEnd];
        }
        for (int i = 1, largeEnd = size(nums) - 1; i < size(nums); i += 2, --largeEnd) {
            result[i] = nums[largeEnd];
        }
        return result;
    }
};

kamyu-c-as-far-from-land-as-possible-01g:
// Time:  O(m * n)
// Space: O(m * n)

class Solution {
public:
    int maxDistance(vector<vector<int>>& grid) {
        static const vector<pair<int, int>> directions{{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        queue<pair<int, int>> q;
        for (int i = 0; i < grid.size(); ++i) {
            for (int j = 0; j < grid[i].size(); ++j) {
                if (grid[i][j]) {
                    q.emplace(i, j);
                }
            }
        }
        if (q.size() == grid.size() * grid[0].size()) {
            return -1;
        }
        int level = -1;
        while (!q.empty()) {
            queue<pair<int, int>> next_q;
            while (!q.empty()) {
                const auto [x, y] = q.front(); q.pop();
                for (const auto& [dx, dy] : directions) {
                    const auto& nx = x + dx;
                    const auto& ny = y + dy;
                    if (!(0 <= nx && nx < grid.size() && 
                          0 <= ny && ny < grid[0].size() && 
                          grid[nx][ny] == 0)) {
                        continue;
                    }
                    next_q.emplace(nx, ny);
                    grid[nx][ny] = 1;
                }
            }
            q = move(next_q);
            ++level;
        }
        return level;
    }
};

