        static vector<pair<int, int>> directions{{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        int r = -1, c = -1;
        for (int i = 0; i < 8 && r == -1; ++i) {
            for (int j = 0; j < 8; ++j) {
                if (board[i][j] == 'R') {
                    tie(r, c) = make_pair(i, j);
                    break;
                }
