        int result = 0;
        for (const auto& d : directions) {
            int nr, nc;
            tie(nr, nc) = make_pair(r + d.first, c + d.second);
            while (0 <= nr && nr < 8 && 0 <= nc && nc < 8) {
                if (board[nr][nc] == 'p') {
                    ++result;
                }
                if (board[nr][nc] != '.') {
                    break;
                }
                tie(nr, nc) = make_pair(nr + d.first, nc + d.second);
            }
        }
        return result;
    }
};

