};

kamyu-c-balance-a-binary-search-tree-019:
// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */

// dfs solution with stack
class Solution {
public:
    TreeNode* balanceBST(TreeNode* root) {
        return sortedArrayToBst(inorderTraversal(root));
    }

private:
    TreeNode *sortedArrayToBst(const vector<int>& arr) {
        TreeNode *result = nullptr;
        vector<tuple<int, int, TreeNode**>> stk = {{0, arr.size(), &result}};
        while (!stk.empty()) {
            const auto [i, j, ret] = stk.back(); stk.pop_back();
            if (i >= j) {
                continue;
            }
            const auto& mid = i + (j - i) / 2;
            *ret = new TreeNode(arr[mid]);
            stk.emplace_back(mid + 1, j, &((*ret)->right));
            stk.emplace_back(i, mid, &((*ret)->left));
        }
        return result;
    }

    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> result;
        vector<pair<TreeNode *, bool>> stk;
        stk.emplace_back(root, false);
        while (!stk.empty()) {
            const auto [node, visited] = stk.back(); stk.pop_back();
            if (!node) {
                continue;
            }
            if (visited) {
                result.emplace_back(node->val);
            } else {
                stk.emplace_back(node->right, false);
                stk.emplace_back(node, true);
                stk.emplace_back(node->left, false);
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(h)
// dfs solution with recursion
class Solution2 {
public:
    TreeNode* balanceBST(TreeNode* root) {
        vector<int> arr;
        inorderTraversalHelper(root, &arr);
        return sortedArrayToBstHelper(arr, 0, arr.size());
    }

private:
    TreeNode *sortedArrayToBstHelper(const vector<int>& arr, int i, int j) {
        if (i >= j) {
            return nullptr;
        }
        const auto& mid = i + (j - i) / 2;
        auto result = new TreeNode(arr[mid]);
        result->left = sortedArrayToBstHelper(arr, i, mid);
        result->right = sortedArrayToBstHelper(arr, mid + 1, j);
        return result;
    }

    void inorderTraversalHelper(TreeNode* root, vector<int> *arr) {
        if (!root) {
            return;
        }
        inorderTraversalHelper(root->left, arr);
        arr->emplace_back(root->val);
        inorderTraversalHelper(root->right, arr);
    }
};

kamyu-c-balanced-k-factor-decomposition-:
// Time:  precompute: O(rlogr)
//        runtime:    O(k * (logn)^(k - 1))
// Space: O(rlogr)

// backtracking, number theory
const auto& factors = [](int n) {
    vector<vector<int>> result(n + 1);
    for (int i = 1; i <= n; ++i) {
        for (int j = i; j <= n; j += i) {
            result[j].emplace_back(i);
        }
    }
    return result;
};

const int MAX_N = 1e5;
const auto& FACTORS = factors(MAX_N);
class Solution {
public:
    vector<int> minDifference(int n, int k) {
        vector<int> result, curr;
        function<void (int)> backtracking = [&](int remain) {
            const int start = !empty(curr) ? curr.back() : 1;
            if (size(curr) == k - 1) {
                if (remain >= start) {
                    curr.emplace_back(remain);
                    if (empty(result) || result.back() - result[0] > curr.back() - curr[0]) {
                        result = curr;
                    }
                    curr.pop_back();
                }
                return;
            }
            const auto& factors = FACTORS[remain];
            for (auto it = lower_bound(cbegin(factors), cend(factors), start); it != cend(factors); ++it) {
                curr.emplace_back(*it);
                backtracking(remain / *it);
                curr.pop_back();
            }
        };

        backtracking(n);
        return result;
    }
};

// Time:  O(k * (n^(1/2) * n^(1/4) * n^(1/8) * n^(1/6) + n^(1/2) * n^(1/4) * n^(1/8) + n^(1/2) * n^(1/4) + n^(1/2))) <= O(k^2 * n)
// Space: O(k)
// backtracking, number theory
class Solution2 {
public:
    vector<int> minDifference(int n, int k) {
        vector<int> result, curr;
        function<void (int)> backtracking = [&](int remain) {
            const int start = !empty(curr) ? curr.back() : 1;
            if (size(curr) == k - 1) {
                if (remain >= start) {
                    curr.emplace_back(remain);
                    if (empty(result) || result.back() - result[0] > curr.back() - curr[0]) {
                        result = curr;
                    }
                    curr.pop_back();
                }
                return;
            }
            for (int i = 1; i * i <= remain; ++i) {
                if (remain % i) {
                    continue;
                }
                const int j = remain / i;
                if (i >= start) {
                    curr.emplace_back(i);
                    backtracking(j);
                    curr.pop_back();
                }
                if (j == i) {
                    continue;
                }
                if (j >= start) {
                    curr.emplace_back(j);
                    backtracking(i);
                    curr.pop_back();
                }
            }
        };

        backtracking(n);
        return result;
    }
};

