class Solution {
public:
    vector<int> bestTower(vector<vector<int>>& towers, vector<int>& center, int radius) {
        int best = -1, best_x = -1, best_y = -1;
        for (const auto& t : towers) {
            const auto& x = t[0], &y = t[1], &q = t[2];
            if (!(abs(x - center[0]) + abs(y - center[1]) <= radius)) {
                continue;
