        vector<int64_t> bought(k, NEG_INF);
        vector<int64_t> sold(k, NEG_INF);
        vector<int64_t> result(k + 1);
        for (const auto& x : prices) {
            for (int i = k - 1; i >= 0; --i) {
                if (bought[i] != NEG_INF) {
