        for (int i = 0; i < size(nums); ++i) {
            for (int prev = i, curr = nums[i];
                 curr >= 0 && curr != i;
                 tie(prev, curr) = pair(curr, ~nums[prev])) {
                tie(nums[prev], nums[curr]) = pair(~nums[curr], (prev == i) ? ~nums[prev] : nums[prev]);
