class Solution {
public:
    string digitSum(string s, int k) {
        while (size(s) > k) {
            string new_s;
            for (int i = 0, curr = 0; i < size(s); ++i) {
                curr += s[i] - '0';
                if (i % k == k - 1 || i == size(s) - 1) {
