        if (s.length() != t.length()) {
            return false;
        }
        vector<int> cnt(26);
        for (int i = 0; i < s.length(); ++i) {
            int diff = (cnt.size() + t[i] - s[i]) % cnt.size();
            if (diff && cnt[diff] * cnt.size() + diff > k) {
                return false;
            }
            ++cnt[diff];
        }
        return true;
    }
};

kamyu-c-can-i-win-02s3yf3:
// Time:  O(n!)
// Space: O(n)

class Solution {
public:
    bool canIWin(int maxChoosableInteger, int desiredTotal) {
        if ((1 + maxChoosableInteger) * (maxChoosableInteger / 2) < desiredTotal) {
            return false;
        }
        unordered_map<int, int> lookup;
        return canIWinHelper(maxChoosableInteger, desiredTotal, 0, &lookup);
    }

private:
    int canIWinHelper(int maxChoosableInteger, int desiredTotal,
                      int visited, unordered_map<int, int> *lookup) {

        if  (lookup->find(visited) != lookup->end()) {
            return (*lookup)[visited];
        }
        int mask = 1;
        for (int i = 0; i < maxChoosableInteger; ++i) {
            if (!(visited & mask)) {
                if (i + 1 >= desiredTotal ||
                    !canIWinHelper(maxChoosableInteger, desiredTotal - (i + 1), visited | mask, lookup)) {
                    (*lookup)[visited] = true;
                    return true;
                }
            }
            mask <<= 1;
        }
        (*lookup)[visited] = false;
        return false;
    }
};

kamyu-c-can-make-arithmetic-progression-:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool canMakeArithmeticProgression(vector<int>& arr) {
        const auto m = *min_element(cbegin(arr), cend(arr));
        const auto& d = (*max_element(cbegin(arr), cend(arr)) - m) / (arr.size() - 1);
        if (!d) {
            return true;
        }
        for (int i = 0; i < arr.size();) {
            if (arr[i] == m + i * d) {
                ++i;
            } else {
                const auto& diff = arr[i] - m;
                if (diff % d || diff / d >= arr.size() || arr[i] == arr[diff / d]) {
                    return false;
                }
                swap(arr[i], arr[diff / d]);
            }
        }
        return true;
    }
};

