        for (int i = 0; i < s1.length(); ++i) {
            if (s1[i] < s2[i]) {
                flag1 = false;
            }
            if (s2[i] < s1[i]) {
                flag2 = false;
            }
            if (!flag1 && !flag2) {
                return false;
            }
        }
        return true;
    }
};

// Time:  O(nlogn)
// Space: O(1)
