        return isBreak(s1, s2) || isBreak(s2, s1);
    }

private:
    bool isBreak(const string& s1, const string& s2) {
        int i = 0;
        for (; i < s1.length(); ++i) {
            if (!(s1[i] >= s2[i])) {
                break;
            }
        }
        return (i == s1.length());
    }
};

kamyu-c-check-if-a-string-contains-all-b:
// Time:  O(n * k)
// Space: O(2^k)

class Solution {
public:
    bool hasAllCodes(string s, int k) {
        unordered_set<int> lookup;
        const int base = 1 << k;
        if (base > s.length()) {
            return false;
        }
        int num = 0;
        for (int i = 0; i < s.length(); ++i) {
            num = (num << 1) + (s[i] - '0');
            if (i >= k - 1) {
                lookup.emplace(num);
                num -= (s[i - k + 1] - '0') * (base >> 1);
            }
        }
        return lookup.size() == base;
    }
};

// Time:  O(n * k)
// Space: O(k * 2^k)
class Solution2 {
public:
    bool hasAllCodes(string s, int k) {
        unordered_set<string> lookup;
        const int base = 1 << k;
        if (base > s.length()) {
            return false;
        }
        for (int i = 0; i + k - 1 < s.length(); ++i) {
            lookup.emplace(s.substr(i, k));
        }
        return lookup.size() == base;
    }
};

kamyu-c-check-if-a-string-is-a-valid-seq:
// Time:  O(n)
// Space: O(w)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
// bfs solution
class Solution {
public:
    bool isValidSequence(TreeNode* root, vector<int>& arr) {
        vector<TreeNode *> q = {root};
        for (int depth = 0; depth < arr.size(); ++depth) {
            vector<TreeNode *> new_q;
            while (!q.empty()) {
                const auto node = q.back(); q.pop_back();
                if (!node || node->val != arr[depth]) {
                    continue;
                }
                if (depth + 1 == arr.size() && node->left == node->right) {
                    return true;
                }
                new_q.emplace_back(node->left);
                new_q.emplace_back(node->right);            
            }
            q = move(new_q);
        }
        return false;
    }
};

// Time:  O(n)
// Space: O(h)
// dfs solution with stack
class Solution2 {
public:
    bool isValidSequence(TreeNode* root, vector<int>& arr) {
        vector<pair<TreeNode *, int>> s = {{root, 0}};
        while (!s.empty()) {
            const auto [node, depth] = s.back(); s.pop_back();
            if (!node || depth == arr.size() || node->val != arr[depth]) {
                continue;
            }
            if (depth + 1 == arr.size() && node->left == node->right) {
                return true;
            }
            s.emplace_back(node->right, depth + 1);   
            s.emplace_back(node->left, depth + 1);
        }
        return false;
    }
};

// Time:  O(n)
// Space: O(h)
// dfs solution with recursion
class Solution3 {
public:
    bool isValidSequence(TreeNode* root, vector<int>& arr) {
        return dfs(root, arr, 0);
    }

private:
    bool dfs(TreeNode *node, const vector<int>& arr, int depth) {
        if (!node || depth == arr.size() || node->val != arr[depth]) {
            return false;
        }
        if (depth + 1 == arr.size() && node->left == node->right) {
            return true;
        }
        return dfs(node->left, arr, depth + 1) || dfs(node->right, arr, depth + 1);
    }
};

