// Time:  O(m * n * k), k is the max number of consecutive digits in s1 and s2
// Space: O(min(m, n) * k)
// bottom-up dp
class Solution3 {
public:
    bool possiblyEquals(string s1, string s2) {
        static const int MAX_DIGIT_LEN = 3;
        static const int w = 1 + MAX_DIGIT_LEN;

        if (size(s1) < size(s2)) {
            swap(s1, s2);
        }
        vector<vector<unordered_set<int>>> dp(w, vector<unordered_set<int>>(size(s2) + 1));
        dp[0][0].emplace(0);
        for (int i = 0; i <= size(s1); ++i) {
            if (i >= 1) {
                dp[(i - 1) % w] = vector<unordered_set<int>>(size(s2) + 1);
            }
            if (i != size(s1) && s1[i] == '0') {
                continue;
            }
            for (int j = 0; j <= size(s2); ++j) {
                for (const auto& k : dp[i % w][j]) {
                    if (i != size(s1) && j != size(s2) && s1[i] == s2[j] && k == 0) {
                        dp[(i + 1) % w][j + 1].emplace(k);
                    }
                    if (k <= 0 && i != size(s1)) {
                        if (!isdigit(s1[i])) {
                            if (k) {
                                dp[(i + 1) % w][j].emplace(k + 1);
                            }
                        } else if (s1[i] != '0') {
                            int curr = 0;
                            for (int ni = i; ni < size(s1) && isdigit(s1[ni]); ++ni) {
                                curr = curr * 10 + (s1[ni] - '0');
                                dp[(ni + 1) % w][j].emplace(k + curr);
                            }
                        }
                    }
                    if (k >= 0 && j != size(s2)) {
                        if (!isdigit(s2[j])) {
                            if (k) {
                                dp[i % w][j + 1].emplace(k - 1);
                            }
                        } else if (s2[j] != '0') {
                            int curr = 0;
                            for (int nj = j; nj < size(s2) && isdigit(s2[nj]); ++nj) {
                                curr = curr * 10 + (s2[nj] - '0');
                                dp[i % w][nj + 1].emplace(k - curr);
                            }
                        }
                    }
                }
            }
        }
        return dp[size(s1) % w][size(s2)].count(0);
    }
};

kamyu-c-check-if-any-element-has-prime-f:
// Time:  precompute: O(MAX_N)
//        runtime: O(n)
// Space: O(MAX_N)

// number theory, freq table
vector<int> linear_sieve_of_eratosthenes(int n) {  // Time: O(n), Space: O(n)
    vector<int> spf(n + 1, -1);
    vector<int> primes;
    for (int i = 2; i <= n; ++i) {
        if (spf[i] == -1) {
            spf[i] = i;
            primes.emplace_back(i);
        }
        for (const auto& p : primes) {
            if (i * p > n || p > spf[i]) {
                break;
            }
            spf[i * p] = p;
        }
    }
    return spf;
}

const int MAX_N = 100;
const auto& SPF = linear_sieve_of_eratosthenes(MAX_N);
class Solution {
public:
    bool checkPrimeFrequency(vector<int>& nums) {
        unordered_map<int, int> cnt;
        for (const auto& x : nums) {
            ++cnt[x];
        }
        return any_of(cbegin(cnt), cend(cnt), [](const auto& x) {
            return SPF[x.second] == x.second;
        });
    }
};

