kamyu-c-check-if-there-is-a-path-with-eq:
// Time:  O(m * n)
// Space: O(n)

// dp
class Solution {
public:
    bool isThereAPath(vector<vector<int>>& grid) {
        if ((size(grid) + size(grid[0]) - 1) % 2) {
            return false;
        }
        vector<vector<int>> dp_left(2, vector<int>(size(grid[0]) + 1, numeric_limits<int>::max()));
        dp_left[0][1] = dp_left[1][0] = 0;
        vector<vector<int>> dp_right(2, vector<int>(size(grid[0]) + 1, numeric_limits<int>::min()));
        dp_right[0][1] = dp_right[1][0] = 0;
        for (int i = 0; i < size(grid); ++i) {
            for (int j = 0; j < size(grid[0]); ++j) {
                dp_left[(i + 1) % 2][j + 1] = min(dp_left[i % 2][j + 1], dp_left[(i + 1) % 2][j]) + grid[i][j];
                dp_right[(i + 1) % 2][j + 1] = max(dp_right[i % 2][j + 1], dp_right[(i + 1) % 2][j]) + grid[i][j];
            }
        }
        return dp_left[size(grid) % 2].back() <= (size(grid) + size(grid[0]) - 1) / 2 &&
               (size(grid) + size(grid[0]) - 1) / 2 <= dp_right[size(grid) % 2].back();
    }
};

kamyu-c-check-if-there-is-a-valid-parent:
// Time:  O((m * n) * (m + n) / 32)
// Space: O(n * (m + n) / 32)

// dp with bitsets
class Solution {
public:
    bool hasValidPath(vector<vector<char>>& grid) {
        if ((size(grid) + size(grid[0]) - 1) % 2 == 1) {
            return false;
        }
        vector<bitset<100>> dp(size(grid[0]) + 1);
        for (int i = 0; i < size(grid); ++i) {
            dp[0][0] = !i;
            for (int j = 0; j < size(grid[0]); ++j) {
                dp[j + 1] = (grid[i][j] == '(') ? (dp[j] | dp[j + 1]) << 1: (dp[j] | dp[j + 1]) >> 1;
            }
        }
        return dp.back()[0];
    }
};

// Time:  O(m * n)
// Space: O(n)
// dp, optimized from solution1 (wrong answer)
class Solution_WA {
public:
    bool hasValidPath(vector<vector<char>>& grid) {
        const int MAX_M = 100;
        const int MAX_N = 100;;
        if ((size(grid) + size(grid[0]) - 1) % 2 == 1) {
            return false;
        }
        vector<pair<int, int>> dp(size(grid[0]) + 1, {MAX_M + MAX_N, -(MAX_M + MAX_N)});
        for (int i = 0; i < size(grid); ++i) {
            dp[0] = !i ? pair(0, 0) : pair(MAX_M + MAX_N, -(MAX_M + MAX_N));
            for (int j = 0; j < size(grid[0]); ++j) {
                const int d = (grid[i][j] == '(') ? 1 : -1;
                dp[j + 1] = {min(dp[j + 1].first, dp[j].first) + d, max(dp[j + 1].second, dp[j].second) + d};
                // bitset pattern is like xxx1010101xxxx (in fact, it is not always true in this problem where some paths are invalid)
                if (dp[j + 1].second < 0) {
                    dp[j + 1] = {MAX_M + MAX_N, -(MAX_M + MAX_N)};
                } else {
                    dp[j + 1].first = max(dp[j + 1].first, dp[j + 1].second % 2);
                }
            }
        }
        return dp.back().first == 0;
    }
};

kamyu-c-check-if-there-is-a-valid-partit:
// Time:  O(n)
// Space: O(1)

// dp
class Solution {
public:
    bool validPartition(vector<int>& nums) {
        vector<int> dp(4);
        dp[0] = 1;
        for (int i = 0; i < size(nums); ++i) {
            dp[(i + 1) % 4] = 0;
            if (i - 1 >= 0 && nums[i] == nums[i - 1]) {
                dp[(i + 1) % 4] |= dp[((i + 1) - 2) % 4];
            }
            if (i - 2 >= 0 &&
                ((nums[i] == nums[i - 1] && nums[i - 1] == nums[i - 2]) ||
                 (nums[i] == nums[i - 1] + 1 && nums[i] == nums[i - 2] + 2))) {
                dp[(i + 1) % 4] |= dp[((i + 1) - 3) % 4];
            }
        }
        return dp[size(nums) % 4];
    }
};

kamyu-c-check-if-there-is-a-valid-path-i:
// Time:  O(m * n)
// Space: O(1)

class Solution {
public:
    bool hasValidPath(vector<vector<int>>& grid) {
        static const pair<int, int> E = {0,  1}, S = {1,  0},
                                    W = {0, -1}, N = {-1, 0};
        static const vector<vector<pair<int, int>>> directions = {
            {W, E}, {N, S},
            {W, S}, {S, E},
            {W, N}, {N, E}
        };

        for (auto [r, c] : directions.at(grid[0][0] - 1)) {
            if (!(0 <= r && r < grid.size() &&
                  0 <= c && c < grid[0].size())) {
                continue;
            }
            int pr = 0, pc = 0;
            while (r != grid.size() - 1 || c != grid[0].size() - 1) {
                bool is_found = false;
                for (const auto& [dx, dy] : directions.at(grid[r][c] - 1)) {
                    const auto& [nr, nc] = pair(r + dx, c + dy);
                    if ((nr == pr && nc == pc) ||
                        !(0 <= nr && nr < grid.size() &&
                          0 <= nc && nc < grid[0].size())) {
                        continue;
                    }
                    const auto& dirs = directions.at(grid[nr][nc] - 1);
                    if (find(cbegin(dirs), cend(dirs), pair(-dx, -dy)) == cend(dirs)) {
                        continue;
                    }
                    tie(pr, pc, r, c) = tuple(r, c, nr, nc);
                    is_found = true;
                    break;
                }
                if (!is_found) {
                    return false;
                }
            }
            return true;
        }
        return grid.size() == 1 && grid[0].size() == 1;
    }
};

