// Space: O(1)

class Solution {
public:
    bool arrayStringsAreEqual(vector<string>& word1, vector<string>& word2) {
        int idx1 = 0, idx2 = 0, arrIdx1 = 0, arrIdx2 = 0;
        while (arrIdx1 < size(word1) && arrIdx2 < size(word2)) {
            if (word1[arrIdx1][idx1] != word2[arrIdx2][idx2]) {
                break;
            }
            ++idx1;
            if (idx1 == size(word1[arrIdx1])) {
                idx1 = 0;
                ++arrIdx1;
            }
            ++idx2;
            if (idx2 == size(word2[arrIdx2])) {
                idx2 = 0;
                ++arrIdx2;
            }
        }
        return arrIdx1 == size(word1) && arrIdx2 == size(word2);
    }
};

kamyu-c-check-if-word-can-be-placed-in-c:
// Time:  O(m * n)
// Space: O(1)

class Solution {
public:
    bool placeWordInCrossword(vector<vector<char>>& board, string word) {
        for (int d = 0; d < 2; ++d) {
            reverse(begin(word), end(word));
            for (int transposed = 0; transposed < 2; ++transposed) {
                for (int i = 0; i < get_r(board, transposed); ++i) {
                    auto it = begin(word);
                    bool matched = true;
                    for (int j = 0; j < get_c(board, transposed); ++j) {
                        const char c = get_val(board, i, j, transposed);
                        if (c == '#') {
                            if (it == end(word) && matched) {
                                return true;
                            }
                            it = begin(word);
                            matched = true;
                            continue;
                        }
                        if (!matched) {
                            continue;
                        }
                        matched = it != end(word) && (c == (*it++) || c == ' ');
                    }
                    if (it == end(word) && matched) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

private:
    int get_r(const vector<vector<char>>& mat, bool transposed) {
        return !transposed ? size(mat) : size(mat[0]);
    }

    int get_c(const vector<vector<char>>& mat, bool transposed) {
        return !transposed ? size(mat[0]) : size(mat);
    }

    int get_val(const vector<vector<char>>& mat, int i, int j, bool transposed) {
        return !transposed ? mat[i][j] : mat[j][i];
    }
};

