kamyu-c-cherry-pickup-0yarqns:
// Time:  O(n^3)
// Space: O(n^2)

class Solution {
public:
    int cherryPickup(vector<vector<int>>& grid) {
        // dp holds the max # of cherries two k-length paths can pickup.
        // The two k-length paths arrive at (i, k - i) and (j, k - j), 
        // respectively.
        const int n = grid.size();
        vector<vector<int>> dp(n, vector<int>(n, -1));
        dp[0][0] = grid[0][0];

        const int max_len = 2 * (n - 1);
        for (int k = 1; k <= max_len; ++k) {
            for (int i = min(k, n - 1); i >= max(0, k - n + 1); --i) {  // 0 <= i < n, 0 <= k-i < n
                for (int j = min(k , n - 1); j >= i; --j) {             // i <= j < n, 0 <= k-j < n
                    if (grid[i][k - i] == -1 ||
                        grid[j][k - j] == -1) {
                        dp[i][j] = -1;
                        continue;
                    }
                    int cnt = grid[i][k - i] + ((i == j) ? 0 : grid[j][k - j]);
                    int max_cnt = -1;
                    static const vector<pair<int, int>> directions{{0, 0}, {-1, 0}, {0, -1}, {-1, -1}};
                    for (const auto& direction : directions) {
                        const auto ii = i + direction.first;
                        const auto jj = j + direction.second;
                        if (ii >= 0 && jj >= 0 && dp[ii][jj] >= 0) {
                            max_cnt = max(max_cnt, dp[ii][jj] + cnt);
                        }
                    }
                    dp[i][j] = max_cnt;
                }
            }
        }
        return max(dp[n - 1][n - 1], 0);
    }
};

kamyu-c-choose-edges-to-maximize-score-i:
// Time:  O(n)
// Space: O(n)

// iterative dfs, tree dp
class Solution {
public:
    long long maxScore(vector<vector<int>>& edges) {
        vector<vector<pair<int, int>>> adj(size(edges));
        for (int i = 1; i < size(edges); ++i) {
            adj[edges[i][0]].emplace_back(i, edges[i][1]);
        }

        const auto& iter_dfs = [&]() {
            vector<pair<int64_t, int64_t>> result(size(adj));
            vector<pair<int, int>> stk = {{1, 0}};
            while (!empty(stk)) {
                const auto [step, u] = stk.back(); stk.pop_back();
                if (step == 1) {
                    if (empty(adj[u])) {
                        continue;
                    }
                    stk.emplace_back(2, u);
                    for (const auto& [v, _] : adj[u]) {
                        stk.emplace_back(1, v);
                    }
                } else if (step == 2) {
                    int64_t without_u = 0;
                    for (const auto& [v, _] : adj[u]) {
                        without_u += max(result[v].first, result[v].second);
                    }
                    int64_t with_u = 0;
                    for (int i = 0; i < size(adj[u]); ++i) {
                        const auto& [v, w] = adj[u][i];
                        with_u = max(with_u, without_u - max(result[v].first, result[v].second) + (result[v].second + w));
                    }
                    result[u] = make_pair(with_u, without_u);
                }
            }
            return max(result[0].first, result[0].second);
        };

        return iter_dfs();
    }
};

// Time:  O(n)
// Space: O(n)
// dfs, tree dp
class Solution2 {
public:
    long long maxScore(vector<vector<int>>& edges) {
        vector<vector<pair<int, int>>> adj(size(edges));
        for (int i = 1; i < size(edges); ++i) {
            adj[edges[i][0]].emplace_back(i, edges[i][1]);
        }

        const function<pair<int64_t, int64_t>(int)> dfs = [&](int u) {
            if (empty(adj[u])) {
                return make_pair<int64_t, int64_t>(0, 0);
            }
            vector<pair<int64_t, int64_t>> children;
            int64_t without_u = 0;
            for (const auto& [v, _] : adj[u]) {
                children.emplace_back(dfs(v));
                without_u += max(children.back().first, children.back().second);
            }
            int64_t with_u = 0;
            for (int i = 0; i < size(adj[u]); ++i) {
                with_u = max(with_u, without_u - max(children[i].first, children[i].second) + (children[i].second + adj[u][i].second));
            }
            return make_pair(with_u, without_u);
        };

        const auto& result = dfs(0);
        return max(result.first, result.second);
    }
};

kamyu-c-choose-k-elements-with-maximum-s:
// Time:  O(nlogn)
// Space: O(n)

// sort, greedy, two pointers, heap
class Solution {
public:
    vector<long long> findMaxSum(vector<int>& nums1, vector<int>& nums2, int k) {
        vector<long long> result(size(nums1));
        priority_queue<int, vector<int>, greater<int>> min_heap;
        vector<int> idxs(size(nums1));
        iota(begin(idxs), end(idxs), 0);
        sort(begin(idxs), end(idxs), [&](const auto& a, const auto& b) {
            return nums1[a] < nums1[b];
        });
        int64_t total = 0;
        for (int i = 0, j = 0; i < size(idxs); ++i) {
            for (; nums1[idxs[j]] < nums1[idxs[i]]; ++j) {
                total += nums2[idxs[j]];
                min_heap.emplace(nums2[idxs[j]]);
                if (size(min_heap) == k + 1) {
                    total -= min_heap.top(); min_heap.pop();
                }
            }
            result[idxs[i]] = total;
        }
        return result;
    }
};

