// Space: O(n)

// hash table
class Solution {
public:
    vector<int> solveQueries(vector<int>& nums, vector<int>& queries) {
        vector<int> dist(size(nums), size(nums));
        unordered_map<int, int> left;
        for (int i = 0; i < 2 * size(nums) - 1; ++i) {
            const auto& x = nums[i % size(nums)];
            if (left.count(x)) {
                dist[i % size(nums)] = min(dist[i % size(nums)], i - left[x]);
            }
            left[x] = i;
        }
        unordered_map<int, int> right;
        for (int i = 2 * size(nums) - 2; i >= 0; --i) {
            const auto& x = nums[i % size(nums)];
            if (right.count(x)) {
                dist[i % size(nums)] = min(dist[i % size(nums)], right[x] - i);
            }
            right[x] = i;
        }
        vector<int> result(size(queries), -1);
        for (int i = 0; i < size(queries); ++i) {
            if (dist[queries[i]] < size(nums)) {
                result[i] = dist[queries[i]];
            }
        }
        return result;
    }
};

kamyu-c-closest-fair-integer-0o0qywp:
// Time:  O(logn)
// Space: O(logn)

// constructive algorithms, greedy
class Solution {
public:
    int closestFair(int n) {
        const auto& digits = to_string(n);
        string result;
        if (size(digits) % 2 == 0) {
            vector<int> left(2);
            for (const auto& d : digits) {
                ++left[(d - '0') % 2];
            }
            if (left[0] == size(digits) / 2) {
                return n;
            }
            for (int i = size(digits) - 1; i >= size(digits) / 2; --i) {
                --left[(digits[i] - '0') % 2];
                vector<int> right = {static_cast<int>(size(digits)) / 2 - left[0],
                                     static_cast<int>(size(digits)) / 2 - left[1]};
                if (any_of(cbegin(right), cend(right), [](const auto& x) { return x < 0; })) {
                    continue;
                }
                const char d = (right[((digits[i] + 1) - '0') % 2] - 1 >= 0) ? digits[i] + 1 : digits[i] + 2;
                if (d > '9') {
                    continue;
                }
                --right[(d - '0') % 2];
                result.append(digits, 0, i);
                result.append(1, d);
                result.append(right[0], '0');
                result.append(right[1], '1');
                break;
            }
        }
        if (empty(result)) {
            const int l = size(digits) / 2 + 1;
            result.append(1, '1');
            result.append(l, '0');
            result.append(l - 1, '1');
        }
        return stoi(result);
    }
};

kamyu-c-closest-leaf-in-a-binary-tree-06:
// Time:  O(n)
// Space: O(n)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    int findClosestLeaf(TreeNode* root, int k) {
        unordered_map<int, vector<int>> neighbors;
        unordered_set<int> leaves;
        traverse(root, &neighbors, &leaves);
        vector<int> q{k};
        unordered_set<int> lookup{k};
        while (!q.empty()) {
            vector<int> next_q;
            for (const auto& u : q) {
                if (leaves.count(u)) {
                    return u;
                }
                for (const auto& v : neighbors[u]) {
                    if (lookup.count(v)) {
                        continue;
                    }
                    lookup.emplace(v);
                    next_q.emplace_back(v);
                }
            }
            swap(q, next_q);
        }
        return 0;
    }

private:
    void traverse(TreeNode *node,
                  unordered_map<int, vector<int>> *neighbors,
                  unordered_set<int> *leaves) {

        if (!node) {
            return;
        }
        if (!node->left && !node->right) {
            leaves->emplace(node->val);
            return;
        }
        if (node->left) {
            (*neighbors)[node->val].emplace_back(node->left->val);
            (*neighbors)[node->left->val].emplace_back(node->val);
            traverse(node->left, neighbors, leaves);
        }
        if (node->right) {
            (*neighbors)[node->val].emplace_back(node->right->val);
            (*neighbors)[node->right->val].emplace_back(node->val);
            traverse(node->right, neighbors, leaves);
        }
    }
};

